import math

def dew_point(t_c: float, rh: float) -> float:
    if rh <= 0.0 or rh > 100.0:
        raise ValueError("Relative humidity must be greater than 0 and at most 100.")

    a = 17.62
    b = 243.12

    gamma = math.log(rh / 100.0) + (a * t_c) / (b + t_c)
    return (b * gamma) / (a - gamma)

import re

_UNIT_SECONDS = {
    "d": 86400,
    "h": 3600,
    "m": 60,
    "s": 1,
}

_PATTERN = re.compile(r"([0-9]+d)?([0-9]+h)?([0-9]+m)?([0-9]+s)?")

def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("empty duration")

    match = _PATTERN.fullmatch(s)
    if match is None:
        raise ValueError("invalid duration")

    total = 0
    for token in match.groups():
        if token is not None:
            total += int(token[:-1]) * _UNIT_SECONDS[token[-1]]

    return total

def merge_intervals(iv: list[tuple[float, float]]) -> list[tuple[float, float]]:
    intervals = sorted(iv)
    merged: list[tuple[float, float]] = []

    for start, end in intervals:
        if start > end:
            raise ValueError("Interval start must be <= end")

        if not merged:
            merged.append((start, end))
        else:
            last_start, last_end = merged[-1]

            if start <= last_end:
                merged[-1] = (last_start, max(last_end, end))
            else:
                merged.append((start, end))

    return merged

from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity: int) -> None:
        if not isinstance(capacity, int) or capacity <= 0:
            raise ValueError("capacity must be a positive integer")

        self.capacity = capacity
        self.cache = OrderedDict()

    def get(self, key):
        if key not in self.cache:
            return -1

        self.cache.move_to_end(key)
        return self.cache[key]

    def put(self, key, value):
        if key in self.cache:
            self.cache[key] = value
            self.cache.move_to_end(key)
            return

        if len(self.cache) >= self.capacity:
            self.cache.popitem(last=False)

        self.cache[key] = value
        self.cache.move_to_end(key)

import heapq

def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    nodes = set(deps.keys())
    for prerequisites in deps.values():
        nodes.update(prerequisites)

    successors = {}
    indegree = {node: 0 for node in nodes}

    for node, prerequisites in deps.items():
        unique_prerequisites = set(prerequisites)
        for prereq in unique_prerequisites:
            successors.setdefault(prereq, []).append(node)
            indegree[node] += 1

    available = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(available)

    order = []

    while available:
        node = heapq.heappop(available)
        order.append(node)

        for successor in successors.get(node, []):
            indegree[successor] -= 1
            if indegree[successor] == 0:
                heapq.heappush(available, successor)

    if len(order) != len(nodes):
        raise ValueError("zyklische Abhängigkeiten")

    return order

def evaluate(expr: str) -> float:
    def tokenize(s: str) -> list:
        tokens = []
        i = 0

        def is_digit(ch: str) -> bool:
            return "0" <= ch <= "9"

        while i < len(s):
            ch = s[i]

            if ch.isspace():
                i += 1
                continue

            if ch in "+-*/()":
                tokens.append(ch)
                i += 1
                continue

            if ch.isdigit() or ch == ".":
                start = i
                dot_seen = False

                if ch == ".":
                    dot_seen = True
                    i += 1

                while i < len(s):
                    c = s[i]
                    if c == ".":
                        if dot_seen:
                            raise ValueError("Ungültige Dezimalzahl")
                        dot_seen = True
                        i += 1
                    elif is_digit(c):
                        i += 1
                    else:
                        break

                number_text = s[start:i]

                if not any(is_digit(c) for c in number_text):
                    raise ValueError("Ungültige Dezimalzahl")

                try:
                    tokens.append(float(number_text))
                except ValueError as exc:
                    raise ValueError("Ungültige Dezimalzahl") from exc

                continue

            raise ValueError("Ungültiges Zeichen")

        return tokens

    tokens = tokenize(expr)
    output = []
    operators = []
    precedence = {
        "+": 1,
        "-": 1,
        "*": 2,
        "/": 2,
    }
    expect_operand = True

    def apply_operator(op: str) -> None:
        if op == "u":
            if not output:
                raise ValueError("Ungültiger Ausdruck")
            output.append(-output.pop())
        else:
            if len(output) < 2:
                raise ValueError("Ungültiger Ausdruck")
            right = output.pop()
            left = output.pop()

            if op == "+":
                output.append(left + right)
            elif op == "-":
                output.append(left - right)
            elif op == "*":
                output.append(left * right)
            elif op == "/":
                output.append(left / right)

    for token in tokens:
        if token == "(":
            if not expect_operand:
                raise ValueError("Ungültiger Ausdruck")

            operators.append("(")
            expect_operand = True

        elif token == ")":
            if expect_operand:
                raise ValueError("Ungültiger Ausdruck")

            while operators and operators[-1] != "(" and operators[-1] != "u":
                apply_operator(operators.pop())

            if not operators or operators[-1] != "(":
                raise ValueError("Ungültige Klammern")

            operators.pop()

            while operators and operators[-1] == "u":
                apply_operator(operators.pop())

            expect_operand = False

        elif isinstance(token, float):
            if not expect_operand:
                raise ValueError("Ungültiger Ausdruck")

            output.append(token)

            while operators and operators[-1] == "u":
                apply_operator(operators.pop())

            expect_operand = False

        elif token == "-":
            if expect_operand:
                operators.append("u")
            else:
                while operators and operators[-1] != "(" and operators[-1] != "u":
                    if precedence[operators[-1]] >= precedence["-"]:
                        apply_operator(operators.pop())
                    else:
                        break

                operators.append("-")
                expect_operand = True

        elif token in ("+", "*", "/"):
            if expect_operand:
                raise ValueError("Ungültiger Ausdruck")

            while operators and operators[-1] != "(" and operators[-1] != "u":
                if precedence[operators[-1]] >= precedence[token]:
                    apply_operator(operators.pop())
                else:
                    break

            operators.append(token)
            expect_operand = True

        else:
            raise ValueError("Ungültiger Ausdruck")

    if expect_operand:
        raise ValueError("Ungültiger Ausdruck")

    while operators:
        op = operators.pop()

        if op == "(":
            raise ValueError("Ungültige Klammern")

        apply_operator(op)

    if len(output) != 1:
        raise ValueError("Ungültiger Ausdruck")

    return float(output[0])

def crc16_ccitt(data: bytes) -> int:
    crc = 0xFFFF
    polynomial = 0x1021

    for byte in data:
        crc ^= byte << 8

        for _ in range(8):
            if crc & 0x8000:
                crc = (crc << 1) ^ polynomial
            else:
                crc <<= 1

            crc &= 0xFFFF

    return crc

def sliding_median(values: list[float], k: int) -> list[float]:
    if k < 1:
        raise ValueError("k must be at least 1")

    n = len(values)
    if k > n:
        raise ValueError("k must not exceed len(values)")

    coords = sorted(set(values))
    index = {value: i + 1 for i, value in enumerate(coords)}
    m = len(coords)
    bit = [0] * (m + 1)
    top_bit = 1 << (m.bit_length() - 1)

    def add(i: int, delta: int) -> None:
        while i <= m:
            bit[i] += delta
            i += i & -i

    def kth(target: int) -> int:
        idx = 0
        acc = 0
        bitmask = top_bit
        while bitmask:
            nxt = idx + bitmask
            if nxt <= m and acc + bit[nxt] < target:
                acc += bit[nxt]
                idx = nxt
            bitmask >>= 1
        return idx + 1

    odd = k % 2 == 1
    median_rank = (k + 1) // 2
    lower_rank = k // 2
    upper_rank = k // 2 + 1

    for i in range(k):
        add(index[values[i]], 1)

    def median() -> float:
        if odd:
            return float(coords[kth(median_rank) - 1])

        left = kth(lower_rank) - 1
        right = kth(upper_rank) - 1
        return (coords[left] + coords[right]) / 2.0

    result = [0.0] * (n - k + 1)
    result[0] = median()

    for start in range(k, n):
        add(index[values[start - k]], -1)
        add(index[values[start]], 1)
        result[start - k + 1] = median()

    return result

import math


class RunningStats:
    def __init__(self) -> None:
        self._count = 0
        self._mean = 0.0
        self._m2 = 0.0

    def add(self, x: float) -> None:
        self._count += 1
        delta = x - self._mean
        self._mean += delta / self._count
        delta2 = x - self._mean
        self._m2 += delta * delta2

    @property
    def count(self) -> int:
        return self._count

    @property
    def mean(self) -> float:
        if self._count == 0:
            return 0.0
        return self._mean

    @property
    def variance(self) -> float:
        if self._count < 2:
            return 0.0
        return max(0.0, self._m2 / (self._count - 1))

    @property
    def std(self) -> float:
        variance = self.variance
        if variance == 0.0:
            return 0.0
        return math.sqrt(variance)

from math import exp


def rh_after_mixing(t1, rh1, m1, t2, rh2, m2, p=101325.0) -> tuple[float, float]:
    if not (m1 > 0.0 and m2 > 0.0):
        raise ValueError("Massenstroms must be > 0")

    if p <= 0.0:
        raise ValueError("p must be > 0")

    def saturation_pressure(t: float) -> float:
        denom = 243.12 + t
        if denom <= 0.0:
            raise ValueError("invalid temperature for Magnus formula")
        return 611.2 * exp(17.62 * t / denom)

    def humidity_ratio(t: float, rh: float) -> float:
        e = (rh / 100.0) * saturation_pressure(t)

        # Partial pressure must stay below total pressure for x = 0.622 * e / (p - e).
        if e >= p:
            e = p * (1.0 - 1e-12)

        return 0.622 * e / (p - e)

    x1 = humidity_ratio(t1, rh1)
    x2 = humidity_ratio(t2, rh2)

    m_total = m1 + m2

    t_mix = (m1 * t1 + m2 * t2) / m_total
    x_mix = (m1 * x1 + m2 * x2) / m_total

    if x_mix > 0.0:
        e_mix = x_mix * p / (0.622 + x_mix)
    else:
        e_mix = 0.0

    es_mix = saturation_pressure(t_mix)
    if es_mix <= 0.0:
        es_mix = 1e-12

    rh_mix = 100.0 * e_mix / es_mix

    if rh_mix < 0.0:
        rh_mix = 0.0
    elif rh_mix > 100.0:
        rh_mix = 100.0

    return (float(t_mix), float(rh_mix))
